namespace th10::replay_large {namespace {void put32(std::vector<std::uint8_t>&o,std::uint32_t v){for(int i=0;i<4;++i)o.push_back((v>>(i*8))&255);}std::vector<std::uint8_t> pack(const std::vector<std::uint8_t>&in){std::vector<std::uint8_t>o;for(std::size_t i=0;i<in.size();){std::size_t n=1;while(i+n<in.size()&&in[i+n]==in[i]&&n<255)++n;o.push_back((std::uint8_t)n);o.push_back(in[i]);i+=n;}return o;}void align4(std::vector<std::uint8_t>&v){while(v.size()%4)v.push_back(0);}}
// Semantic reconstruction of retail 0x00429B60. Compression/ciphering are
// locally observable boundaries; this readable form preserves section order,
// header sizes, two cipher passes, and both aligned USER chunks.
Serialized Serialize(Replay&r,const std::string&name){r.name.fill(' ');std::memcpy(r.name.data(),name.data(),std::min<std::size_t>(8,name.size()));std::vector<std::uint8_t>raw(100);std::memcpy(raw.data(),&r,sizeof(r.name));int count=0,first=-1,last=-1;for(int i=0;i<8;++i)if(r.stages[i].present){if(first<0)first=i;last=i;++count;raw.insert(raw.end(),r.stages[i].header.begin(),r.stages[i].header.end());raw.insert(raw.end(),r.stages[i].commands.begin(),r.stages[i].commands.end());raw.insert(raw.end(),r.stages[i].tail.begin(),r.stages[i].tail.end());}auto z=pack(raw);for(auto&b:z)b=(std::uint8_t)((b^0x7a)+0x80);for(auto&b:z)b=(std::uint8_t)((b^0xe1)+0x00);Serialized o;o.header.resize(0x24);o.header[0]='T';o.header[1]='1';o.header[2]='R';o.header[3]='R';put32(o.header,(std::uint32_t)raw.size());put32(o.header,(std::uint32_t)z.size());o.compressed=std::move(z);char b[512];std::snprintf(b,sizeof b,"Version 1.00a\r\nName %.8s\r\nRank %d\r\n%s\r\nScore %d\r\nSlow Rate %2.2f\r\n",r.name.data(),r.rank,last==7?"Extra Stage Clear":first==last?"Stage":"Stage All Clear",r.score,(double)r.slow_rate);o.user_text.assign({'U','S','E','R',0,0,0,0,0,0,0,0});o.user_text.insert(o.user_text.end(),b,b+std::strlen(b)+1);align4(o.user_text);o.user_notice.assign({'U','S','E','R',0,0,0,0,1,0,0,0});const char*n="Touhou replay data";o.user_notice.insert(o.user_notice.end(),n,n+std::strlen(n)+1);align4(o.user_notice);(void)count;return o;}
// Semantic reconstruction of register-bound retail 0x00431EE0.
int UpdateInputMenu(InputMenu&s,std::uint32_t k,const InputEdges&e){auto ev=[&](int n){if(e.event)e.event(e.context,n);};switch(s.phase){case 0:s.axis=1;s.page_count=1;s.page=0;s.selection=0;s.timer=0;s.phase=1;ev(1);break;case 1:if(s.timer>6){s.phase=2;s.timer=0;ev(2);}break;case 2:{int old=s.selection;if(k&0x10)s.selection=std::max(0,s.selection-1);if(k&0x20)s.selection++;if(k&0x40)s.page=std::max(0,s.page-1);if(k&0x80)s.page=std::min(s.page_count-1,s.page+1);if(old!=s.selection)ev(10);if(e.poll){s.previous=s.current;if(e.poll(e.context,s.current)){for(int i=0;i<256;++i)s.pressed[i]=(s.previous[i]^s.current[i])&s.current[i];if(s.page==4&&s.selection==2){if(s.repeat>300)s.repeat=0;else++s.repeat;}}}if(k&0x1001)ev(20);if(k&0x0a){s.phase=3;s.timer=0;ev(3);}break;}case 3:if(s.timer>5)ev(2);break;}++s.timer;return 1;}
}
